import { useTranslation } from '../../../hooks/useTranslation';
import React, { useEffect, useState } from "react";
import { Box, Typography, Avatar, IconButton } from "@mui/material";
import FavoriteIcon from "@mui/icons-material/Favorite";
import ReplyIcon from "@mui/icons-material/Reply";
import Cookies from "js-cookie";
import { User } from "firebase/auth";

interface ReplyProps {
  reply: any;
  user: User | null;
  onReply?: (reply: any) => void;
  onReplyClick?: (parentId: number, username: string) => void;
}

const Reply: React.FC<ReplyProps> = ({ reply, user, onReply, onReplyClick }) => {
  const { t } = useTranslation();
  const [likes, setLikes] = useState(reply.likes || 0);
  const [liked, setLiked] = useState(false);
  const userId = Cookies.get("userId");
  const wpToken = Cookies.get("wpToken");

  const handleLike = async () => {
    if (!user || !wpToken) return;
    
    const action = liked ? "unlike" : "like";
    try {
      const response = await fetch(
        `${process.env.REACT_APP_WP_API_URL_CUSTOM}/like-comment/${reply?.id}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Basic ${btoa(`${user?.email || ""}:${wpToken}`)}`,
          },
          body: JSON.stringify({ action }),
        }
      );
      const data = await response.json();
      setLikes(data.likes);
      setLiked(!liked);
    } catch (error) {
      console.error("Error liking reply:", error);
    }
  };

  const likedUsers = reply?.liked_users ? Object.values(reply.liked_users) : [];

  useEffect(() => {
    if (userId && likedUsers.includes(parseInt(userId))) {
      setLiked(true);
    }
  }, [reply.likes, userId, likedUsers]);

  // Function to process @ mentions in the content
  const processMentions = (content: string) => {
    if (!content) return content;
    
    // Pattern to match @username mentions (alphanumeric, underscore, dot)
    const mentionPattern = /@(\w+(?:\.\w+)?)/g;
    
    return content.replace(mentionPattern, (match, username) => {
      return `<span style="color: #1976d2; font-weight: 500; cursor: pointer;" onclick="alert('User: ${username}')">@${username}</span>`;
    });
  };

  const processedContent = reply?.content?.rendered 
    ? processMentions(reply.content.rendered) 
    : '';

  return (
    <Box
      sx={{
        display: "flex",
        alignItems: "flex-start",
        mb: 1.5,
        ml: 3, // Indent replies
        pl: 2,
        borderLeft: "2px solid #e0e0e0",
      }}
    >
      <Avatar
        alt={reply.author_name}
        src={reply.author_avatar_urls?.[48]}
        sx={{ mr: 1, width: "15px", height: "15px", borderRadius: "0px" }}
      />
      <Box sx={{ flex: 1 }}>
        <Typography variant="body2" sx={{ fontWeight: "bold", color: "black", fontSize: "0.65rem" }}>
          {reply.author_name}
          {reply.parent_author_name && (
            <>
              {" "}
              <Typography component="span" sx={{ color: "#777", fontWeight: "normal", fontSize: "0.5rem" }}>
                → @{reply.parent_author_name}
              </Typography>
            </>
          )}
        </Typography>
        <Typography
          variant="body2"
          sx={{
            px: 1,
            mt: -1.5,
            lineHeight: 1.2,
            fontSize: "0.65rem",
            color: "black",
            wordBreak: "break-word",
            whiteSpace: "pre-wrap",
            overflowWrap: "break-word",
            textAlign: "justify",
            fontFamily: "'Alegreya Sans', sans-serif",
            '& a': {
              color: '#a1a1a1',
              textDecoration: 'underline',
              transition: 'color 0.2s ease',
              '&:hover': {
                color: 'black',
              }
            }
          }}
          dangerouslySetInnerHTML={{ __html: processedContent }}
        />
        <Box sx={{ display: "flex", alignItems: "center", mt: -2.5 }}>
          <IconButton
            size="small"
            onClick={handleLike}
            color={liked || likedUsers.includes(parseInt(userId ? userId : '0')) ? "warning" : "secondary"}
            sx={{ width: "20px", height: "20px" }}
          >
            <FavoriteIcon
              sx={{ 
                color: liked || likedUsers.includes(parseInt(userId ? userId : '0')) ? "warning" : "secondary", 
                width: "15px",
                height: "15px"
              }}
              fontSize="small"
            />
          </IconButton>
          <Typography
            variant="body2"
            sx={{
              ml: 0,
              mt: "-1.5px",
              color: "#777",
              fontSize: "0.55rem",
              fontWeight: 800,
              lineHeight: 'normal',
              fontFamily: "'Alegreya Sans', sans-serif",
            }}
          >
            {likes}
          </Typography>
          {user && onReplyClick && (
            <Box
              onClick={() => {
                onReplyClick(reply.id, reply.author_name || "Unknown");
              }}
              sx={{
                display: "flex",
                alignItems: "center",
                gap: 0.5,
                cursor: "pointer",
                ml: 1,
                "&:hover": {
                  opacity: 0.8,
                },
              }}
            >
              <ReplyIcon
                sx={{
                  fontSize: "0.75rem",
                  color: "#777",
                }}
              />
              <Typography
                variant="body2"
                sx={{
                  color: "#777",
                  fontSize: "0.6rem",
                  fontWeight: 500,
                  fontFamily: "'Alegreya Sans', sans-serif",
                }}
              >{String(t('comments.reply'))}</Typography>
            </Box>
          )}
        </Box>
      </Box>
    </Box>
  );
};

export default Reply;

