import { useTranslation } from '../hooks/useTranslation';
import React from 'react';
import { 
  Container, 
  Typography, 
  Box, 
  Button, 
  Paper, 
  Grid, 
  Divider,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Link,
  useTheme
} from '@mui/material';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import { Navigate } from 'react-router-dom';
import { redirectToPaymentLink, SUBSCRIPTION_PLANS, TRIAL_PERIOD_DAYS } from '../services/stripe';

interface SubscribePageProps {
  user: any | null;
  loggedIn: boolean;
}

const SubscribePage: React.FC<SubscribePageProps> = ({ user, loggedIn }) => {
  const { t } = useTranslation();
  const theme = useTheme();
  
  // Redirect to login if not logged in
  if (!loggedIn) {
    return <Navigate to="/login?redirect=subscribe" replace />;
  }
  
  const handleSubscribe = (plan: 'MONTHLY' | 'YEARLY') => {
    if (!user?.email) {
      console.error('No user email found');
      return;
    }
    
    redirectToPaymentLink(plan, user.email);
  };
  
  const features = [
    // 'Unlimited Study Notes',
    String(t('moreUI.advancedSearch')),
    String(t('moreUI.personalHighlights')),
    String(t('moreUI.addComments')),
    String(t('moreUI.adFree'))
  ];
  
  return (
    <Container maxWidth="lg" sx={{ py: 8, mt: 5 }}>
      <Box sx={{ textAlign: 'center', mb: 6 }}>
        <Typography variant="h4" component="h1" gutterBottom>{String(t('subscriptionUI.choose'))}</Typography>
        <Typography variant="subtitle1" color="text.secondary">{String(t('subscriptionUI.intro'))}</Typography>
        <Typography
          variant="body2"
          color="primary"
          sx={{ mt: 1, fontWeight: 600 }}
        >
          {String(t('subscriptionUI.trial', { count: TRIAL_PERIOD_DAYS }))}
        </Typography>
      </Box>
      
      <Grid container spacing={4} justifyContent="center">
        {/* Monthly Plan */}
        <Grid item xs={12} md={5}>
          <Paper 
            elevation={3}
            sx={{
              p: 4,
              height: '100%',
              display: 'flex',
              flexDirection: 'column',
              borderRadius: 2,
              transition: 'transform 0.3s ease-in-out',
              '&:hover': {
                transform: 'translateY(-5px)'
              }
            }}
          >
            <Typography variant="h5" component="h2" gutterBottom>
              {String(t('subscriptionUI.monthlyName'))}
            </Typography>
            
            <Box sx={{ display: 'flex', alignItems: 'baseline', mb: 2 }}>
              <Typography variant="h3" component="span">
                £{SUBSCRIPTION_PLANS.MONTHLY.amount}
              </Typography>
              <Typography variant="subtitle1" color="text.secondary" sx={{ ml: 1 }}>
                /{String(t('subscriptionUI.month'))}
              </Typography>
            </Box>
            
            <Typography variant="body2" color="text.secondary" paragraph>
              {String(t('subscriptionUI.full'))}
            </Typography>
            
            <Divider sx={{ my: 2 }} />
            
            <List sx={{ flexGrow: 1 }}>
              {features.map((feature) => (
                <ListItem key={feature} sx={{ p: 1 }}>
                  <ListItemIcon sx={{ minWidth: 36 }}>
                    <CheckCircleOutlineIcon color="primary" fontSize="small" />
                  </ListItemIcon>
                  <ListItemText primary={feature} />
                </ListItem>
              ))}
            </List>
            
            <Button 
              variant="contained"
              color="primary"
              size="large"
              fullWidth
              sx={{ mt: 3 }}
              onClick={() => handleSubscribe('MONTHLY')}
            >
              {String(t('subscriptionUI.startTrial', { count: TRIAL_PERIOD_DAYS }))}
            </Button>
          </Paper>
        </Grid>
        
        {/* Yearly Plan */}
        <Grid item xs={12} md={5}>
          <Paper 
            elevation={3}
            sx={{
              p: 4,
              height: '100%',
              display: 'flex',
              flexDirection: 'column',
              borderRadius: 2,
              border: `2px solid ${theme.palette.primary.main}`,
              transition: 'transform 0.3s ease-in-out',
              '&:hover': {
                transform: 'translateY(-5px)'
              }
            }}
          >
            <Box sx={{ position: 'relative', mb: 2 }}>
              <Typography variant="h5" component="h2" gutterBottom>
                {String(t('subscriptionUI.yearlyName'))}
              </Typography>
              
              <Box 
                sx={{ 
                  position: 'absolute', 
                  top: -8, 
                  right: -16, 
                  backgroundColor: theme.palette.secondary.main,
                  color: theme.palette.secondary.contrastText,
                  px: 2,
                  py: 0.5,
                  borderRadius: 1,
                  transform: 'rotate(5deg)',
                  fontSize: '0.875rem',
                  fontWeight: 'bold'
                }}
              >{String(t('subscriptionUI.best'))}</Box>
            </Box>
            
            <Box sx={{ display: 'flex', alignItems: 'baseline', mb: 2, mt: -2.5 }}>
              <Typography variant="h3" component="span">
                £{SUBSCRIPTION_PLANS.YEARLY.amount}
              </Typography>
              <Typography variant="subtitle1" color="text.secondary" sx={{ ml: 1 }}>
                /{String(t('subscriptionUI.year'))}
              </Typography>
            </Box>
            
            <Typography variant="body2" color="text.secondary" paragraph>
              {String(t('subscriptionUI.fullYear'))}
            </Typography>
            
            <Divider sx={{ my: 2 }} />
            
            <List sx={{ flexGrow: 1 }}>
              {features.map((feature) => (
                <ListItem key={feature} sx={{ p: 1 }}>
                  <ListItemIcon sx={{ minWidth: 36 }}>
                    <CheckCircleOutlineIcon color="primary" fontSize="small" />
                  </ListItemIcon>
                  <ListItemText primary={feature} />
                </ListItem>
              ))}
            </List>
            
            <Button 
              variant="contained"
              color="secondary"
              size="large"
              fullWidth
              sx={{ mt: 3 }}
              onClick={() => handleSubscribe('YEARLY')}
            >
              {String(t('subscriptionUI.startTrial', { count: TRIAL_PERIOD_DAYS }))}
            </Button>
          </Paper>
        </Grid>
      </Grid>
      
      <Box sx={{ textAlign: 'center', mt: 6 }}>
        <Typography variant="body2" color="text.secondary">{String(t('subscriptionUI.termsPrefix'))}<Link href="https://revelationary.org/terms-of-service/">{String(t('login.termsOfService'))}</Link>{String(t('login.agreeToTermsConnector'))}<Link href="https://revelationary.org/privacy-policy/">{String(t('login.privacyPolicy'))}</Link>.
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>{String(t('subscriptionUI.questions'))}<Link href="https://revelationary.org/contact/">{String(t('subscriptionUI.contact'))}</Link>
        </Typography>
      </Box>
    </Container>
  );
};

export default SubscribePage;
