import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { useTranslation } from '../../hooks/useTranslation';
import i18n from '../../i18n/config';

interface SEOProps {
  title?: string;
  description?: string;
  image?: string;
  url?: string;
  type?: 'website' | 'article' | 'webapp';
  verse?: {
    book?: string;
    chapter?: number;
    verse?: number | string;
    text?: string;
  };
  keywords?: string[];
  author?: string;
}

/**
 * SEO Component for dynamic meta tags and structured data
 * Makes the site AI-friendly by providing rich, structured information
 */
const SEO: React.FC<SEOProps> = ({
  title,
  description,
  image = 'https://revelationary.online/logo512.png',
  url,
  type = 'website',
  verse,
  keywords,
  author = 'Revelationary Team'
}) => {
  const location = useLocation();
  const { t, language } = useTranslation();
  const baseUrl = 'https://revelationary.online';
  
  // Get current language code for SEO (en, zh-hant, de, es)
  const currentLang = language || i18n.language || 'en';
  
  // Map language codes to locale formats
  const getLocaleCode = (lang: string): string => {
    const map: Record<string, string> = {
      'en': 'en_US',
      'zh-hant': 'zh_TW',
      'de': 'de_DE',
      'es': 'es_ES',
      'it': 'it_IT',
      'cs': 'cs_CZ',
      'sv': 'sv_SE',
      'id': 'id_ID',
      'nl': 'nl_NL',
      'vi': 'vi_VN', 'th': 'th_TH'
    };
    return map[lang] || 'en_US';
  };
  
  // Get hreflang code (ISO 639-1 format)
  const getHreflangCode = (lang: string): string => {
    const map: Record<string, string> = {
      'en': 'en',
      'zh-hant': 'zh-Hant',
      'de': 'de',
      'es': 'es',
      'it': 'it',
      'cs': 'cs',
      'sv': 'sv',
      'id': 'id',
      'nl': 'nl',
      'vi': 'vi', 'th': 'th'
    };
    return map[lang] || 'en';
  };
  
  // Get translated SEO content with fallbacks
  const seoTitle = title || (t('seo.title', { defaultValue: 'Free Bible Study Online - Interactive Scripture Study Tools | Revelationary' }) as string);
  const seoDescription = description || (t('seo.description', { defaultValue: 'Study the Bible online with our free Bible study app. Access interactive Bible study tools including verse highlighting, community comments, reading progress tracking, and multilingual support. Perfect for online Bible study.' }) as string);
  const seoKeywordsArray = keywords || (t('seo.keywords', { returnObjects: true, defaultValue: ['bible study online', 'online bible study', 'free bible study online'] }) as string[]);
  const seoKeywords = Array.isArray(seoKeywordsArray) ? seoKeywordsArray : ['bible study online', 'online bible study', 'free bible study online'];
  
  // Build URL (for hash routing, we can't easily add lang param, so rely on cookies/localStorage)
  const currentUrl = url || `${baseUrl}${location.pathname}${location.hash || ''}`;
  
  // Enhanced description with verse context if available
  const enhancedDescription = verse 
    ? `${seoDescription} ${t('common.loading', { defaultValue: 'Currently viewing' })}: ${verse.book} ${verse.chapter}:${verse.verse} - "${verse.text?.substring(0, 100)}..."`
    : seoDescription;

  // Enhanced title with verse context if available
  const enhancedTitle = verse
    ? `${verse.book} ${verse.chapter}:${verse.verse} | ${seoTitle}`
    : seoTitle;

  // Generate structured data
  const generateStructuredData = () => {
    const schemas: any[] = [];

    // Main WebApplication schema
    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'WebApplication',
      'name': 'Revelationary Online',
      'alternateName': 'Revelationary',
      'description': 'A free, comprehensive Bible study application with verse highlighting, community comments, media insights, reading progress tracking, and multilingual support (English, Chinese, German).',
      'url': baseUrl,
      'applicationCategory': 'EducationalApplication',
      'operatingSystem': 'Web Browser',
      'offers': {
        '@type': 'Offer',
        'price': '0',
        'priceCurrency': 'USD'
      },
      'featureList': [
        'Bible verse highlighting',
        'Community comments and discussions',
        'Reading progress tracking',
        'Multilingual support (English, Chinese, German)',
        'Verse search',
        'Bookmarks',
        'Media and science insights',
        'Linked verses'
      ],
      'browserRequirements': 'Requires JavaScript. Requires HTML5.',
      'inLanguage': ['en', 'zh-Hant', 'de', 'es'],
      'isAccessibleForFree': true,
      'publisher': {
        '@type': 'Organization',
        'name': 'Revelationary',
        'url': 'https://revelationary.org'
      }
    });

    // WebSite schema with search
    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'WebSite',
      'name': 'Revelationary Online',
      'url': baseUrl,
      'description': 'Free Bible study app with advanced features for studying scripture',
      'inLanguage': ['en', 'zh-Hant', 'de', 'es'],
      'potentialAction': {
        '@type': 'SearchAction',
        'target': {
          '@type': 'EntryPoint',
          'urlTemplate': `${baseUrl}/?search={search_term_string}`
        },
        'query-input': 'required name=search_term_string'
      }
    });

    // If viewing a specific verse, add Book schema
    if (verse && verse.book && verse.chapter && verse.verse) {
      schemas.push({
        '@context': 'https://schema.org',
        '@type': 'Book',
        'name': verse.book,
        'description': `Bible Study: ${verse.book} Chapter ${verse.chapter}, Verse ${verse.verse}`,
        'bookEdition': 'King James Version / Chinese Union Version / Lutherbibel / Reina Valera 1909',
        'inLanguage': currentLang,
        'isPartOf': {
          '@type': 'Book',
          'name': 'The Holy Bible'
        },
        'about': {
          '@type': 'Thing',
          'name': 'Bible Study',
          'description': verse.text || 'Bible verse'
        }
      });

      // Article schema for verse discussions
      schemas.push({
        '@context': 'https://schema.org',
        '@type': 'Article',
        'headline': `${verse.book} ${verse.chapter}:${verse.verse} - Bible Study`,
        'description': `Study and discuss ${verse.book} ${verse.chapter}:${verse.verse} with community insights and commentary`,
        'url': currentUrl,
        'author': {
          '@type': 'Organization',
          'name': 'Revelationary Community'
        },
        'publisher': {
          '@type': 'Organization',
          'name': 'Revelationary',
          'logo': {
            '@type': 'ImageObject',
            'url': `${baseUrl}/logo512.png`
          }
        },
        'about': {
          '@type': 'CreativeWork',
          'name': verse.book,
          'text': verse.text
        }
      });
    }

    // SoftwareApplication schema (enhanced)
    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'SoftwareApplication',
      'name': 'Revelationary Online',
      'applicationCategory': 'EducationalApplication',
      'operatingSystem': 'Web',
      'offers': {
        '@type': 'Offer',
        'price': '0',
        'priceCurrency': 'USD',
        'availability': 'https://schema.org/InStock'
      },
      'aggregateRating': {
        '@type': 'AggregateRating',
        'ratingValue': '5',
        'ratingCount': '1',
        'bestRating': '5',
        'worstRating': '1'
      },
      'description': 'Free Bible study application with verse highlighting, comments, reading progress, and bilingual support',
      'featureList': [
        'Interactive Bible reading',
        'Verse highlighting and bookmarks',
        'Community comments and replies',
        'Reading progress tracking',
        'Multi-language support',
        'Verse search',
        'Media insights'
      ]
    });

    // BreadcrumbList schema
    const breadcrumbs = [
      { name: 'Home', url: baseUrl },
      { name: title, url: currentUrl }
    ];
    if (verse && verse.book) {
      breadcrumbs.splice(1, 0, { name: verse.book, url: `${baseUrl}/#/${verse.book}` });
    }

    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      'itemListElement': breadcrumbs.map((item, index) => ({
        '@type': 'ListItem',
        'position': index + 1,
        'name': item.name,
        'item': item.url
      }))
    });

    // FAQPage schema for common questions - targeting "bible study online" keywords
    schemas.push({
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      'mainEntity': [
        {
          '@type': 'Question',
          'name': 'Is Revelationary Online free?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Yes, Revelationary Online is completely free to use. All features including verse highlighting, comments, bookmarks, and reading progress tracking are available at no cost.'
          }
        },
        {
          '@type': 'Question',
          'name': 'How do I study the Bible online for free?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'You can study the Bible online for free using Revelationary Online. Simply create a free account to access all features including interactive Bible reading, verse highlighting, community comments, reading progress tracking, and multilingual support. No payment required.'
          }
        },
        {
          '@type': 'Question',
          'name': 'What Bible translations are available online?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Revelationary Online supports multiple Bible translations including King James Version (KJV) in English, Chinese Union Version (CUV) in Simplified Chinese, Lutherbibel (LUT) in German, Reina Valera 1909 (RV09) in Spanish, Diodati 1885 in Italian, Bible kralická (BKR) in Czech, Svenska Bibeln (SKB) in Swedish, Alkitab Indonesia (TSI) in Indonesian, Nederlandse Bijbel 1939 (NBG) in Dutch, and Kinh Thánh Việt (OVCB) in Vietnamese. All translations are available for free online Bible study.'
          }
        },
        {
          '@type': 'Question',
          'name': 'What are the best online Bible study tools?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'The best online Bible study tools include verse highlighting, Strong\'s Concordance integration, community comments and discussions, reading progress tracking, bookmarks, verse search, and Bible Project video summaries. Revelationary Online offers all these features for free.'
          }
        },
        {
          '@type': 'Question',
          'name': 'Can I study the Bible online with a group?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Yes, you can study the Bible online with others through Revelationary Online\'s community features. You can comment on Bible verses, reply to other users\' comments, and engage in discussions about scripture. The platform enables collaborative online Bible study.'
          }
        },
        {
          '@type': 'Question',
          'name': 'How does online Bible study work?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Online Bible study with Revelationary Online works by providing interactive tools to read, highlight, and study scripture. You can search for specific verses, read multiple translations, leave comments, track your reading progress, and watch video summaries. Everything is accessible through your web browser for convenient online Bible study.'
          }
        },
        {
          '@type': 'Question',
          'name': 'Can I comment on Bible verses?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Yes, you can comment on any Bible verse, reply to other comments, and engage in discussions with the community. This feature allows you to share insights, ask questions, and learn from others during your online Bible study.'
          }
        },
        {
          '@type': 'Question',
          'name': 'How do I track my Bible reading progress?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'The app automatically tracks your reading progress as you navigate through chapters. You can mark chapters as read to track your progress through the entire Bible. This feature helps you maintain consistency in your online Bible study routine.'
          }
        },
        {
          '@type': 'Question',
          'name': 'Are there study guides available for online Bible study?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Yes, Revelationary Online includes Bible Project video summaries for many books and chapters, providing visual overviews and explanations. These videos serve as study guides to help you understand the context and themes of each biblical book during your online Bible study.'
          }
        },
        {
          '@type': 'Question',
          'name': 'Is online Bible study as effective as traditional methods?',
          'acceptedAnswer': {
            '@type': 'Answer',
            'text': 'Online Bible study can be highly effective when using the right tools. Revelationary Online combines traditional Bible reading with modern interactive features like verse highlighting, Strong\'s Concordance, community discussions, and progress tracking, making online Bible study both convenient and comprehensive.'
          }
        }
      ]
    });

    return schemas;
  };

  const structuredData = generateStructuredData();

  useEffect(() => {
    // Helper function to update or create meta tags
    const updateMetaTag = (name: string, content: string, property?: boolean) => {
      const attribute = property ? 'property' : 'name';
      let element = document.querySelector(`meta[${attribute}="${name}"]`) as HTMLMetaElement;
      if (!element) {
        element = document.createElement('meta');
        element.setAttribute(attribute, name);
        document.head.appendChild(element);
      }
      element.setAttribute('content', content);
    };

    // Update document title
    document.title = enhancedTitle;

    // Set HTML lang attribute dynamically
    document.documentElement.lang = currentLang;
    
    // Update basic meta tags
    updateMetaTag('description', enhancedDescription);
    updateMetaTag('keywords', seoKeywords.join(', '));
    updateMetaTag('author', author);
    updateMetaTag('robots', 'index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1');
    updateMetaTag('googlebot', 'index, follow');
    updateMetaTag('bingbot', 'index, follow');
    updateMetaTag('AI', 'true');
    updateMetaTag('content-type', 'text/html; charset=utf-8');

    // Update Open Graph tags
    updateMetaTag('og:type', type, true);
    updateMetaTag('og:url', currentUrl, true);
    updateMetaTag('og:title', enhancedTitle, true);
    updateMetaTag('og:description', enhancedDescription, true);
    updateMetaTag('og:image', image, true);
    updateMetaTag('og:locale', getLocaleCode(currentLang), true);
    // Add alternate locales
    if (currentLang !== 'en') {
      updateMetaTag('og:locale:alternate', 'en_US', true);
    }
    if (currentLang !== 'zh-hant') {
      updateMetaTag('og:locale:alternate', 'zh_TW', true);
    }
    if (currentLang !== 'de') {
      updateMetaTag('og:locale:alternate', 'de_DE', true);
    }
    if (currentLang !== 'es') {
      updateMetaTag('og:locale:alternate', 'es_ES', true);
    }
    if (currentLang !== 'it') {
      updateMetaTag('og:locale:alternate', 'it_IT', true);
    }
    if (currentLang !== 'cs') {
      updateMetaTag('og:locale:alternate', 'cs_CZ', true);
    }
    if (currentLang !== 'sv') {
      updateMetaTag('og:locale:alternate', 'sv_SE', true);
    }
    if (currentLang !== 'id') {
      updateMetaTag('og:locale:alternate', 'id_ID', true);
    }
    if (currentLang !== 'nl') {
      updateMetaTag('og:locale:alternate', 'nl_NL', true);
    }
    if (currentLang !== 'vi') {
      updateMetaTag('og:locale:alternate', 'vi_VN', true);
    }
    updateMetaTag('og:site_name', 'Revelationary Online', true);

    // Update Twitter tags
    updateMetaTag('twitter:card', 'summary_large_image');
    updateMetaTag('twitter:url', currentUrl);
    updateMetaTag('twitter:title', enhancedTitle);
    updateMetaTag('twitter:description', enhancedDescription);
    updateMetaTag('twitter:image', image);

    // Update canonical URL
    let canonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement;
    if (!canonical) {
      canonical = document.createElement('link');
      canonical.setAttribute('rel', 'canonical');
      document.head.appendChild(canonical);
    }
    canonical.setAttribute('href', currentUrl);

    // Add alternate language links (hreflang tags)
    // For hash routing, we'll include lang parameter to indicate language
    const addAlternateLink = (hreflang: string, lang: string) => {
      let link = document.querySelector(`link[rel="alternate"][hreflang="${hreflang}"]`) as HTMLLinkElement;
      if (!link) {
        link = document.createElement('link');
        link.setAttribute('rel', 'alternate');
        link.setAttribute('hreflang', hreflang);
        document.head.appendChild(link);
      }
      // For hash routing, URLs are the same but we indicate language via hreflang
      // Search engines understand that language is determined by cookies/localStorage
      link.setAttribute('href', currentUrl);
    };

    // Add hreflang for all supported languages
    addAlternateLink('en', 'en');
    addAlternateLink('zh-Hant', 'zh-hant');
    addAlternateLink('de', 'de');
    addAlternateLink('es', 'es');
    addAlternateLink('x-default', 'en'); // Default to English

    // Remove old structured data scripts
    const oldScripts = document.querySelectorAll('script[data-seo-structured-data]');
    oldScripts.forEach(script => script.remove());

    // Add new structured data
    structuredData.forEach((schema, index) => {
      const script = document.createElement('script');
      script.type = 'application/ld+json';
      script.setAttribute('data-seo-structured-data', 'true');
      script.textContent = JSON.stringify(schema, null, 2);
      document.head.appendChild(script);
    });

    // Cleanup function
    return () => {
      // Optionally clean up on unmount if needed
    };
  }, [enhancedTitle, enhancedDescription, currentUrl, type, image, seoKeywords, author, structuredData, currentLang, language]);

  return null; // This component doesn't render anything
};

export default SEO;

