import { z } from "zod";

/** Google's public test key — always passes; must never ship in production. */
const GOOGLE_RECAPTCHA_TEST_SITE_KEY =
  "6LcgGh0rAAAAAJ2LXuSIhbdhzv1636PLcKxGbni0";

const SPAM_CONTENT_PATTERNS: readonly RegExp[] = [
  /\bbtc\b/i,
  /\bbitcoin\b/i,
  /\bethereum\b/i,
  /\bcrypto\b/i,
  /\bwallet\b/i,
  /action\s+required/i,
  /\bvoucher\b/i,
  /\bgift\s+card\b/i,
  /\bmain\s+gift\b/i,
  /\bclick\s+here\b/i,
  /\burgent\b/i,
  /\blimited\s+time\b/i,
  /\bsaved\s+funds\b/i,
  /\baccess\s+your\b/i,
  /access[_\s-]*your/i,
  /saved[_\s-]*funds/i,
  /\bclaim\s+your\b/i,
  /\bwithdraw\b/i,
  /\bfunds\b/i,
  /https?:\/\//i,
  /\bwww\./i,
  /\b[a-z0-9-]+\.(ru|tw|tk|ml|ga|cf|gq|su)\b/i,
];

const DISPLAY_NAME_ALLOWED_PATTERN = /^[\p{L}\p{M}' .-]+$/u;

const hasSpamContent = (value: string): boolean =>
  SPAM_CONTENT_PATTERNS.some((pattern) => pattern.test(value));

const isMostlyUppercase = (value: string): boolean => {
  const letters = value.replace(/[^a-zA-Z]/g, "");
  if (letters.length < 8) {
    return false;
  }
  const uppercaseCount = letters.replace(/[^A-Z]/g, "").length;
  return uppercaseCount / letters.length > 0.6;
};

const hasSuspiciousEmailLocalPart = (email: string): boolean => {
  const localPart = email.split("@")[0] ?? "";
  if (localPart.length === 0) {
    return true;
  }
  if (/\d{4,}/.test(localPart)) {
    return true;
  }
  if ((localPart.match(/\./g) ?? []).length > 4) {
    return true;
  }
  return false;
};

const DisplayNameSchema = z
  .string()
  .trim()
  .min(2, "Please enter your real name")
  .max(60, "Name is too long")
  .refine((value) => !/[0-9@#$%^&*()+=[\]{}|\\<>/]/.test(value), {
    message: "Name cannot contain numbers or special characters",
  })
  .refine((value) => DISPLAY_NAME_ALLOWED_PATTERN.test(value), {
    message: "Name can only contain letters, spaces, hyphens, and apostrophes",
  })
  .refine((value) => !hasSpamContent(value), {
    message: "Please enter your real name",
  })
  .refine((value) => !isMostlyUppercase(value), {
    message: "Please enter your real name",
  });

export type SignupValidationResult = {
  readonly isValid: boolean;
  readonly error?: string;
};

export const validateDisplayName = (name: string): SignupValidationResult => {
  const result = DisplayNameSchema.safeParse(name);
  if (result.success) {
    return { isValid: true };
  }
  const firstIssue = result.error.issues[0];
  return {
    isValid: false,
    error: firstIssue?.message ?? "Please enter your real name",
  };
};

export const validateSignupEmailLocalPart = (
  email: string
): SignupValidationResult => {
  if (hasSuspiciousEmailLocalPart(email)) {
    return {
      isValid: false,
      error: "Please enter a valid email address",
    };
  }
  return { isValid: true };
};

export const getRecaptchaSiteKey = (): string => {
  const configuredKey = process.env.REACT_APP_RECAPTCHA_SITE_KEY?.trim() ?? "";
  if (!configuredKey) {
    return "";
  }
  if (
    process.env.NODE_ENV === "production" &&
    configuredKey === GOOGLE_RECAPTCHA_TEST_SITE_KEY
  ) {
    return "";
  }
  return configuredKey;
};

const WORDPRESS_USERNAME_PATTERN = /^[a-z0-9_-]{3,60}$/;

export const validateWordPressUsername = (
  username: string
): SignupValidationResult => {
  const normalized = username.trim().toLowerCase();
  if (!WORDPRESS_USERNAME_PATTERN.test(normalized)) {
    return { isValid: false, error: "Invalid username" };
  }
  if (hasSpamContent(normalized)) {
    return { isValid: false, error: "Invalid username" };
  }
  return { isValid: true };
};
