/** Localize stored canonical references without changing the scripture or reference numbers. */
export const translateReference = (reference: string, t: (key: string, options?: any) => string | object): string => {
 const match = reference.trim().match(/^(.*?)[ -](\d+)(?::|-)(\d+(?:[a-z]|-\d+)?)$/);
 if (!match || !normalizeBookName(match[1])) return reference;
 return `${translateBookName(match[1], t)} ${match[2]}:${match[3]}`;
};
