import { AuthApiError } from "../services/authApi";
import i18n from '../i18n/config';

export const mapAuthApiErrorMessage = (
  error: unknown,
  fallback: string
): string => {
  if (!(error instanceof AuthApiError)) {
    return fallback;
  }

  switch (error.code) {
    case "captcha_failed":
      return String(i18n.getResource(i18n.language, 'translation', 'authErrors.captcha'));
    case "user_exists":
      return String(i18n.getResource(i18n.language, 'translation', 'authErrors.exists'));
    case "invalid_email":
    case "invalid_name":
    case "invalid_username":
      return String(i18n.getResource(i18n.language, 'translation', error.code === 'invalid_email' ? 'login.invalidEmailAddress' : 'signup.pleaseEnterValidName'));
    case "rate_limited":
      return String(i18n.getResource(i18n.language, 'translation', 'authErrors.rateLimit'));
    case "invalid_token":
    case "missing_token":
      return String(i18n.getResource(i18n.language, 'translation', 'authErrors.expired'));
    default:
      return fallback;
  }
};
