/** One registry binds scripture, interface language and book labels. */
export const editions: Record<string, { locale: string; folder: string }> = {
  kjv: { locale: 'en', folder: 'en-kjv' },
  fbv: { locale: 'en', folder: 'en-fbv' },
  cuv: { locale: 'zh-hant', folder: 'cuv-zh-hant' },
  lut: { locale: 'de', folder: 'lut' },
  'es-rv09': { locale: 'es', folder: 'es-rv09' },
  'it-db1885': { locale: 'it', folder: 'it-db1885' },
  'cs-bkr': { locale: 'cs', folder: 'cs-bkr' },
  'sv-skb': { locale: 'sv', folder: 'sv-skb' },
  'id-tsi': { locale: 'id', folder: 'id-tsi' },
  'nl-nld1939': { locale: 'nl', folder: 'nl-nld1939' },
  'vi-ovcb': { locale: 'vi', folder: 'vi-ovcb' },
  'th-kjv': { locale: 'th', folder: 'th-kjv' },
};
export const localeForEdition = (edition: string): string => editions[edition]?.locale || 'en';
export const bibleBaseForEdition = (edition: string): string => {
  const entry = editions[edition || 'kjv'];
  if (!entry) throw new Error('Unknown Bible edition: ' + edition);
  // Immutable validated revision for the newly converted edition.
  const revision = edition === 'th-kjv' ? '@448e76cc862a3256ee96ba3dddd531476fc03c07' : '';
  return `https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api${revision}/bibles/${entry.folder}/books/`;
};
