interface VideoSources {
  [book: string]: {
    [chapter: number]: string;
  };
}

// Helper function to convert YouTube watch URL to embed URL
const convertToEmbedUrl = (watchUrl: string): string => {
  if (watchUrl.includes('youtube-nocookie.com/embed')) {
    return watchUrl; // Already an embed URL
  }
  // Extract video ID from watch URL
  const videoIdMatch = watchUrl.match(/[?&]v=([^&]+)/);
  if (videoIdMatch && videoIdMatch[1]) {
    return `https://www.youtube-nocookie.com/embed/${videoIdMatch[1]}?controls=0`;
  }
  return watchUrl; // Fallback if can't parse
};

// Helper function to extract YouTube video ID from URL
const extractYouTubeId = (url: string): string | null => {
  // Handle embed URLs
  const embedMatch = url.match(/embed\/([^?]+)/);
  if (embedMatch && embedMatch[1]) {
    return embedMatch[1].split('?')[0];
  }
  // Handle watch URLs
  const watchMatch = url.match(/[?&]v=([^&]+)/);
  if (watchMatch && watchMatch[1]) {
    return watchMatch[1];
  }
  return null;
};

// Helper function to format book name for display
const formatBookName = (book: string): string => {
  return book
    .split('-')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
};

