import { localeForEdition } from '../i18n/editions';
import { useEffect } from 'react';
import { useTranslation } from '../hooks/useTranslation';
import i18n from '../i18n/config';
import Cookies from 'js-cookie';

/**
 * Component that watches for translation changes and updates i18n locale
 * This ensures the translation system is always active and listening for changes
 */
const TranslationWatcher: React.FC = () => {
  const { t, language } = useTranslation();

  // This component doesn't render anything, it just ensures the hook is active
  // The hook will handle all the translation watching
  useEffect(() => {
    // Force initial locale check
    const translation = localStorage.getItem('translation') || Cookies.get('translation') || 'kjv';
    const locale = localeForEdition(translation);
    // kjv, fbv -> en
    
    // Update i18n locale if needed
    if (i18n.language !== locale) {
      i18n.changeLanguage(locale);
    }
  }, []);

  // Debug: Log when language changes (can be removed in production)
  useEffect(() => {
    if (process.env.NODE_ENV === 'development') {
      console.log('TranslationWatcher: Language changed to:', language);
      console.log('TranslationWatcher: Test translation:', t('common.translations'));
      // Test direct i18n access using getFixedT
      try {
        const fixedT = i18n.getFixedT(language, 'translation') as (key: string) => string;
        console.log('TranslationWatcher: getFixedT test:', fixedT('common.translations'));
      } catch (e) {
        console.warn('TranslationWatcher: Error testing getFixedT:', e);
      }
    }
  }, [language, t]);

  return null; // This component doesn't render anything
};

export default TranslationWatcher;
