import CommentIcon from "@mui/icons-material/Comment";
import Box from "@mui/material/Box";
import Tooltip from "@mui/material/Tooltip";
import Typography from "@mui/material/Typography";

import {
  verseCommentChipSx,
  verseCommentIconSx,
} from "../../styles/verseUi";

interface VerseCommentChipProps {
  readonly count: number;
  readonly tooltip: string;
  readonly isSelected: boolean;
  readonly tooltipPlacement?: "left" | "right";
  readonly onClick: (event: React.MouseEvent<HTMLElement>) => void;
}

export function VerseCommentChip({
  count,
  tooltip,
  isSelected,
  tooltipPlacement = "right",
  onClick,
}: VerseCommentChipProps): JSX.Element {
  return (
    <Tooltip title={tooltip} placement={tooltipPlacement} arrow>
      <Box
        sx={verseCommentChipSx(isSelected)}
        onClick={onClick}
        role="button"
        tabIndex={0}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            onClick(event as unknown as React.MouseEvent<HTMLElement>);
          }
        }}
      >
        <CommentIcon sx={verseCommentIconSx(count > 0)} />
        {count > 0 && (
          <Typography
            variant="caption"
            sx={{
              fontSize: { xs: "0.65rem", sm: "0.7rem" },
              fontWeight: { xs: 500, sm: 400 },
              color: (theme) =>
                theme.palette.mode === "light" ? "#555555" : "#e5e5e5",
            }}
          >
            {count}
          </Typography>
        )}
      </Box>
    </Tooltip>
  );
}
