import React, { useState, useEffect, useRef } from "react";
import ReCAPTCHA from "react-google-recaptcha";
import { useNavigate } from "react-router-dom";
import { useTheme, ThemeProvider } from "@mui/material/styles";
import CssBaseline from "@mui/material/CssBaseline";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import Container from "@mui/material/Container";
import TextField from "@mui/material/TextField";
import Button from "@mui/material/Button";
import Checkbox from "@mui/material/Checkbox";
import Paper from "@mui/material/Paper";
import Alert from "@mui/material/Alert";
import { isLoginMaintenanceMode } from "../config/maintenance";
import {
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  signInWithPopup,
  GoogleAuthProvider,
  User,
} from "firebase/auth";
import { auth } from "../firebase"; // Import the initialized auth instance
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import FormControlLabel from "@mui/material/FormControlLabel";
import Link from "@mui/material/Link";
import logo from "../assets/logo512.png";
import { useTranslation } from "../hooks/useTranslation";
import { validateEmail } from "../utils/emailValidation";
import { getRecaptchaSiteKey } from "../utils/signupValidation";
import { mapAuthApiErrorMessage } from "../utils/authApiErrors";
import {
  createWordPressSignupAndStoreCredentials,
  ensureWordPressUser,
  syncWordPressCredentials,
} from "../services/authApi";
import { ConversionEvents } from "../utils/analytics";
import gordonJohnsonImage from "../assets/gordon-johnson3.webp";

function translateEmailValidationError(
  error: string | undefined,
  t: (key: string) => string
): string {
  if (!error) {
    return "";
  }
  if (error === "Email is required") {
    return String(t("login.emailRequired"));
  }
  if (error === "Please enter a valid email address") {
    return String(t("login.pleaseEnterValidEmail"));
  }
  if (error.includes("Don't worry") || error.includes("read the bible")) {
    return String(t("login.blockedEmailDomain"));
  }
  return error;
}

const RECAPTCHA_SITE_KEY = getRecaptchaSiteKey();
const DELAY = 1500;

interface LoginPageProps {
  user: User | null;
}

const LoginPage: React.FC<LoginPageProps> = ({ user }) => {
  const { t, language } = useTranslation();
  const loginMaintenanceMode = isLoginMaintenanceMode();
  const [isSigningUp, setIsSigningUp] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [agreedToTerms, setAgreedToTerms] = useState(false); // terms of service
  const [isOptedOut, setIsOptedOut] = useState(false); // Track if user opted out cookies
  const navigate = useNavigate();

  const theme = useTheme();
  const isDarkMode = theme.palette.mode === "dark";

  const [serverError, setServerError] = useState("");
  const [captchaValue, setCaptchaValue] = useState<string | null>("[empty]");
  const [captchaExpired, setCaptchaExpired] = useState(false);
  const [captchaLoaded, setCaptchaLoaded] = useState(false);

  const recaptchaRef = useRef<ReCAPTCHA>(null);

   useEffect(() => {
      const timer = setTimeout(() => {
        setCaptchaLoaded(true);
      }, DELAY);
      return () => clearTimeout(timer);
    }, []);

    const handleCaptchaChange = (value: string | null) => {
      console.log("Captcha value:", value);
      setCaptchaValue(value);
      if (value === null) {
        setCaptchaExpired(true);
      } else {
        setCaptchaExpired(false);
      }
    };
  
    const asyncScriptOnLoad = () => {
      console.log("reCAPTCHA script loaded");
    };


  const handleGoogleSignIn = async () => {
    const provider = new GoogleAuthProvider();
    try {
      const result = await signInWithPopup(auth, provider);

      if (!result.user) {
        setError(String(t("login.pleaseLoginToContinue")));
        return;
      }
      const firebaseUser = result.user;

      if (firebaseUser.email) {
        const emailValidation = validateEmail(firebaseUser.email);
        if (!emailValidation.isValid) {
          setError(
            translateEmailValidationError(emailValidation.error, t) ||
              String(t("login.emailDomainNotAccepted"))
          );
          return;
        }
      }

      await ensureWordPressUser(firebaseUser, {
        source: "google-signup",
        displayName:
          firebaseUser.displayName ??
          firebaseUser.email?.split("@")[0] ??
          "User",
      });

      ConversionEvents.signUpComplete("google", "login-page");
      navigate("/");
    } catch (error) {
      console.error("Error during Google Sign-In:", error);
      setError(
        mapAuthApiErrorMessage(error, String(t("login.failedToSignUp")))
      );
    }
  };

  const handleSignUp = async (e: any) => {
    e.preventDefault();

    if (!RECAPTCHA_SITE_KEY) {
      setError(
        process.env.NODE_ENV === "development"
          ? "reCAPTCHA is not configured. Add REACT_APP_RECAPTCHA_SITE_KEY to .env and restart the dev server."
          : String(t("login.captchaNotConfigured"))
      );
      return;
    }

    if (!captchaValue || captchaValue === "[empty]") {
      setError(String(t("login.pleaseCompleteCaptcha")));
      return;
    }

    if (!agreedToTerms) {
      setError(String(t("login.agreeToTerms")));
      return;
    }

    // Validate email domain
    const emailValidation = validateEmail(email);
    if (!emailValidation.isValid) {
      setError(
        translateEmailValidationError(emailValidation.error, t) ||
          String(t("login.invalidEmailAddress"))
      );
      return;
    }

    try {
      const userCredential = await createUserWithEmailAndPassword(
        auth,
        email,
        password
      );
      const firebaseUser = userCredential.user;

      await createWordPressSignupAndStoreCredentials(firebaseUser, {
        source: "login-signup",
        recaptchaToken: captchaValue ?? undefined,
      });

      ConversionEvents.signUpComplete("email", "login-page");
      navigate("/");
    } catch (error) {
      console.error("Error signing up:", error);
      setError(
        mapAuthApiErrorMessage(error, String(t("login.failedToSignUp")))
      );
    }
  };

  const handleLogin = async () => {
    try {
      const userCredential = await signInWithEmailAndPassword(
        auth,
        email,
        password
      );
      await syncWordPressCredentials(userCredential.user);
      ConversionEvents.loginComplete("email");
      navigate("/");
    } catch (error) {
      console.error("Error logging in:", error);
      setError(
        mapAuthApiErrorMessage(error, String(t("login.pleaseLoginToContinue")))
      );
    }
  };

  useEffect(() => {
    if (user) {
      void syncWordPressCredentials(user).catch((syncError) => {
        console.warn("WordPress credential sync failed:", syncError);
      });
    }
  }, [user]);

  // Preload LCP image for better performance - run immediately on mount
  useEffect(() => {
    // Check if link already exists to avoid duplicates
    const existingLink = document.querySelector(`link[rel="preload"][href="${gordonJohnsonImage}"]`);

    // Create preload link for WebP image (if not already exists)
    if (typeof window !== 'undefined' && !existingLink && gordonJohnsonImage) {
      const webpLink = document.createElement('link');
      webpLink.rel = 'preload';
      webpLink.as = 'image';
      webpLink.href = gordonJohnsonImage;
      webpLink.type = 'image/webp';
      webpLink.setAttribute('fetchpriority', 'high');
      // Insert at the beginning of head for earlier discovery
      document.head.insertBefore(webpLink, document.head.firstChild);
    }
  }, []); // Empty dependency array - run once on mount

  return (
    <Box 
      sx={{ 
        mt: 8, 
        mb: 4, 
        display: "flex", 
        minHeight: "calc(110vh)",
        alignItems: "center",
        position: "relative",
        backgroundImage: `url(${gordonJohnsonImage})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        backgroundRepeat: "no-repeat",
        "&::before": {
          content: '""',
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: isDarkMode ? "rgba(0, 0, 0, 0.5)" : "rgba(255, 255, 255, 0.7)",
          zIndex: 0,
        },
      }}
    >
      <CssBaseline />
      <Container 
        component="main" 
        maxWidth="sm"
        sx={{
          position: "relative",
          zIndex: 1,
        }}
      >

        {/* Use this for any annoucements */}
        {/* <Typography sx={{ fontSize: 14, fontStyle: 'italic' }}>We suffered a small outage in our database and have had to rollback. Any account made after 25.04.2025 and before 27.04.2025 may need to sign up again. If you did not receive your API password please contact us at info@revelationary.online Thanks and God Bless 
        
        </Typography> */}
        <Paper
          key={language}
          elevation={6}
          sx={{
            p: 4,
            mt: 10,
            display: "flex",
            flexDirection: "column",
            alignItems: "left",
            marginBottom: "1.5rem",
            backgroundColor: (theme) => theme.palette.mode === "light" ? "#fff" : "#000",
          }}
        >
          <Typography
            sx={{ mb: 1, fontSize: "24px", fontWeight: 600, fontFamily: "Arial", textAlign: 'left' }}
            component="h1"
            variant="h5"
            gutterBottom
          >
            {loginMaintenanceMode
              ? String(t("login.maintenanceTitle"))
              : isSigningUp
              ? String(t("login.createAccountHeading"))
              : String(t("login.signIn"))}
          </Typography>

          {loginMaintenanceMode ? (
            <Box sx={{ mt: 2 }}>
              <Alert severity="info" sx={{ mb: 3 }}>
                {String(t("login.maintenanceMessage"))}
              </Alert>
              <Button
                fullWidth
                variant="contained"
                onClick={() => navigate("/")}
                sx={{
                  backgroundColor: (theme) =>
                    theme.palette.mode === "light" ? "#212121" : "#FFF",
                  color: (theme) =>
                    theme.palette.mode === "light" ? "#FFF" : "#212121",
                  "&:hover": {
                    backgroundColor: (theme) =>
                      theme.palette.mode !== "light" ? "#212121" : "#FFF",
                    color: (theme) =>
                      theme.palette.mode !== "light" ? "#FFF" : "#212121",
                  },
                }}
              >
                {String(t("login.continueReading"))}
              </Button>
            </Box>
          ) : isSigningUp && (
            <>
              <Typography sx={{ textAlign: 'left', color: '#979797', fontSize: "16px",  }}>
                {String(t("login.signUpIntro"))}
              </Typography>
              <Box sx={{ mb: 3, textAlign: 'center', alignContent: 'center', alignItems: 'center', justifyContent: 'center', display: 'flex', flexDirection: 'column' }}>
                <Typography
                  sx={{
                    fontSize: "16px",
                    pt: 1,
                    mt: 1,
                    display: "flex",
                    alignItems: "center"
                  }}
                >
                  <CheckCircleIcon
                    fontSize="small"
                    color={
                      !agreedToTerms
                        ? ("disabled" as const)
                        : isOptedOut
                        ? ("disabled" as const)
                        : ("success" as const)
                    }
                    sx={{ mr: 1 }}
                  />
                  {String(t("login.benefitNewsletters"))}
                </Typography>

                <Typography
                  sx={{
                    fontSize: "16px",
                    pt: 1,
                    mt: 1,
                    display: "flex",
                    alignItems: "center"
                  }}
                >
                  <CheckCircleIcon
                    fontSize="small"
                    color={
                      agreedToTerms
                        ? ("success" as const)
                        : ("disabled" as const)
                    }
                    sx={{ mr: 1 }}
                  />
                  {String(t("login.benefitBookmarks"))}
                </Typography>

                <Typography
                  sx={{
                    fontSize: "16px",
                    pt: 1,
                    mt: 1,
                    display: "flex",
                    alignItems: "center",
                  }}
                >
                  <CheckCircleIcon
                    fontSize="small"
                    color={
                      agreedToTerms
                        ? ("success" as const)
                        : ("disabled" as const)
                    }
                    sx={{ mr: 1 }}
                  />
                  {String(t("login.benefitHighlightVerses"))}
                </Typography>
              </Box>
            </>
          )}

          {!loginMaintenanceMode && (
            <>
          {error && (
            <Typography color="error" variant="body2" sx={{ mb: 2 }}>
              {error}
            </Typography>
          )}

          <TextField
            margin="normal"
            size="small"
            required
            fullWidth
            id="email"
            label={String(t("login.emailAddress"))}
            name="email"
            autoComplete="email"
            autoFocus
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            sx={{
              WebkitBoxShadow: "none !important",
              "& .Mui-focused": {
                color: (theme) =>
                  theme.palette.mode === "light"
                    ? "black !important"
                    : "white !important",
                "& .MuiOutlinedInput-notchedOutline": {
                  borderColor: (theme) =>
                    theme.palette.mode === "light"
                      ? "#ccc !important"
                      : "#FFF !important",
                  color: (theme) =>
                    theme.palette.mode === "light"
                      ? "black"
                      : "white !important",
                },
                "& input:-webkit-autofill": {
                  WebkitBoxShadow: "0 0 0 100px #212121AA inset",
                  WebkitTextFillColor: (theme) =>
                    theme.palette.mode === "light" ? "black" : "white",
                  transition: "background-color 5000s ease-in-out 0s",
                },
              },
              "& .MuiInputBase-input": {
                color: (theme) =>
                  theme.palette.mode === "light" ? "black" : "white",
              },
              "& .MuiInputBase-input:-webkit-autofill": {
                WebkitBoxShadow: "0 0 0 100px #212121AA inset",
                WebkitTextFillColor: (theme) =>
                  theme.palette.mode === "light" ? "black" : "white",
                transition: "background-color 5000s ease-in-out 0s",
              },
            }}
          />

          <TextField
            margin="normal"
            size="small"
            required
            fullWidth
            name="password"
            label={String(t("login.password"))}
            type="password"
            id="password"
            autoComplete="current-password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            sx={{
              WebkitBoxShadow: "none !important",
              "& .Mui-focused": {
                color: (theme) =>
                  theme.palette.mode === "light"
                    ? "black !important"
                    : "white !important",
                "& .MuiOutlinedInput-notchedOutline": {
                  borderColor: (theme) =>
                    theme.palette.mode === "light"
                      ? "#ccc !important"
                      : "#FFF !important",
                  color: (theme) =>
                    theme.palette.mode === "light"
                      ? "black"
                      : "white !important",
                },
                "& input:-webkit-autofill": {
                  WebkitBoxShadow: "0 0 0 100px #212121AA inset",
                  WebkitTextFillColor: (theme) =>
                    theme.palette.mode === "light" ? "black" : "white",
                  transition: "background-color 5000s ease-in-out 0s",
                },
              },
              "& .MuiInputBase-input": {
                color: (theme) =>
                  theme.palette.mode === "light" ? "black" : "white",
              },
              "& .MuiInputBase-input:-webkit-autofill": {
                WebkitBoxShadow: "0 0 0 100px #212121AA inset",
                WebkitTextFillColor: (theme) =>
                  theme.palette.mode === "light" ? "black" : "white",
                transition: "background-color 5000s ease-in-out 0s",
              },
            }}
          />
          {isSigningUp && (
            <Box sx={{ width: "100%", mt: 1}}>
            {captchaLoaded && RECAPTCHA_SITE_KEY && (
              <Box sx={{ my: 2, ml: {md: '20%', xs: '15%' } }}>
                <ReCAPTCHA
                  ref={recaptchaRef}
                  sitekey={RECAPTCHA_SITE_KEY}
                  onChange={handleCaptchaChange}
                  asyncScriptOnLoad={asyncScriptOnLoad}
                />
              </Box>
            )}
              <FormControlLabel
                control={
                  <Checkbox
                    checked={agreedToTerms}
                    onChange={(e) => setAgreedToTerms(e.target.checked)}
                  />
                }
                label={
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    align="center"
                    sx={{
                      mt: 0.5,
                      color: "#a1a1a1",
                      fontSize: 13,
                      "& .MuiFormControlLabel-label": {
                        fontSize: 13,
                      },
                    }}
                  >
                    {String(t("login.agreeToTermsPrefix"))}{" "}
                    <Link
                      href="https://revelationary.org/terms-of-service/"
                      target="_blank"
                      rel="noopener noreferrer"
                      sx={{ fontSize: "13px" }}
                    >
                      {String(t("login.termsOfService"))}
                    </Link>{" "}
                    {String(t("login.agreeToTermsConnector"))}{" "}
                    <Link
                      href="https://revelationary.org/privacy-policy/"
                      target="_blank"
                      rel="noopener noreferrer"
                      sx={{ fontSize: "13px" }}
                    >
                      {String(t("login.privacyPolicy"))}
                    </Link>
                  </Typography>
                }
              />
            </Box>
          )}
          <Button
            type="submit"
            fullWidth
            variant="contained"
            sx={{
              mt: 3,
              mb: 2,
              backgroundColor:  (theme) =>
                theme.palette.mode === "light" ? "#212121" : "#FFF",
              color: (theme) =>
                theme.palette.mode === "light" ? "#FFF" : "#212121",
              "&:hover": {
                backgroundColor: (theme) =>
                  theme.palette.mode !== "light" ? "#212121" : "#FFF",
                color: (theme) =>
                theme.palette.mode !== "light" ? "#FFF" : "#212121",
              },
            }}
            onClick={isSigningUp ? handleSignUp : handleLogin}
          >
            {isSigningUp
              ? String(t("login.createAccount"))
              : String(t("login.signIn"))}
          </Button>

          {!isSigningUp && (
            <Button
              type="button"
              fullWidth
              variant="outlined"
              sx={{
                mt: 1,
                mb: 2,
                backgroundColor: "transparent",
                color: (theme) =>
                  theme.palette.mode === "light" ? "#212121" : "#a1a1a1",
                border: (theme) =>
                  theme.palette.mode === "light"
                    ? "1px solid #212121"
                    : "1px solid #a1a1a1",
                "&:hover": {
                  backgroundColor: (theme) =>
                    theme.palette.mode === "light" ? "#212121" : "#FFF",
                  color: (theme) =>
                    theme.palette.mode === "light" ? "#FFF" : "#212121",
                  border: (theme) =>
                    theme.palette.mode === "light"
                      ? "1px solid #212121"
                      : "1px solid #a1a1a1",
                },
              }}
              onClick={handleGoogleSignIn}
            >
              {String(t("login.signInWithGoogle"))}
            </Button>
          )}

          <Typography
            variant="body2"
            color="text.secondary"
            align="left"
            sx={{
              mt: 2,
              display: "flex",
              color: "#a1a1a1",
              "& .MuiFormControlLabel-label": {
                fontSize: "14px",
              },
            }}
          >
            {isSigningUp ? (
              <>
                {String(t("login.alreadyHaveAccount"))}{" "}
                <Button
                  variant="text"
                  sx={{ color: "#a1a1a1", mt: -1, ml: 1 }}
                  onClick={() => setIsSigningUp(false)}
                >
                  {String(t("login.signIn"))}
                </Button>
              </>
            ) : (
              <>
                {String(t("login.dontHaveAccount"))}{" "}
                <Button
                  variant="text"
                  sx={{ color: "#a1a1a1", mt: -1, ml: 1 }}
                  onClick={() => setIsSigningUp(true)}
                >
                  {String(t("login.signUp"))}
                </Button>
              </>
            )}
          </Typography>

          {isSigningUp && (
            <Box sx={{ mt: 2 }}>
              <FormControlLabel
                sx={{
                  display: "flex",
                  color: "#a1a1a1",
                  "& .MuiFormControlLabel-label": {
                    fontSize: "14px",
                  },
                }}
                control={
                  <Checkbox
                    onChange={(e) => setIsOptedOut(e.target.checked)}
                    checked={isOptedOut}
                  />
                }
                label={String(t("login.optOutNewsletters"))}
              />
            </Box>
          )}
            </>
          )}
        </Paper>
      </Container>
    </Box>
  );
};

export default LoginPage;
