import { localeForEdition } from './editions';
import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import Cookies from 'js-cookie';
import thTranslations from './locales/th.json';
import enTranslations from './locales/en.json';
import zhTranslations from './locales/zh-hant.json';
import deTranslations from './locales/de.json';
import esTranslations from './locales/es.json';
import itTranslations from './locales/it.json';
import csTranslations from './locales/cs.json';
import svTranslations from './locales/sv.json';
import idTranslations from './locales/id.json';
import nlTranslations from './locales/nl.json';
import viTranslations from './locales/vi.json';

// Get translation from localStorage/cookies and map to locale
const getTranslation = (): string => {
  const translation = Cookies.get('translation') || localStorage.getItem('translation') || 'kjv';
  return localeForEdition(translation);
};

i18n
  .use(initReactI18next)
  .init({
    resources: {
      th: { translation: thTranslations },
      en: {
        translation: enTranslations,
      },
      'zh-hant': {
        translation: zhTranslations,
      },
      de: {
        translation: deTranslations,
      },
      es: {
        translation: esTranslations,
      },
      it: {
        translation: itTranslations,
      },
      cs: {
        translation: csTranslations,
      },
      sv: {
        translation: svTranslations,
      },
      id: {
        translation: idTranslations,
      },
      nl: {
        translation: nlTranslations,
      },
      vi: {
        translation: viTranslations,
      },
    },
    lng: getTranslation(),
    fallbackLng: 'en',
    interpolation: {
      escapeValue: false, // React already escapes values
    },
    react: {
      useSuspense: false, // Disable suspense to prevent issues
    },
    // Ensure language changes trigger updates
    debug: process.env.NODE_ENV === 'development',
  });

// Watch for changes in translation and update locale
export const updateLocaleFromTranslation = () => {
  const translation = Cookies.get('translation') || localStorage.getItem('translation') || 'kjv';
  const locale = localeForEdition(translation);
  if (i18n.language !== locale) {
    i18n.changeLanguage(locale);
  }
};

export default i18n;
