/** Resolve names from the same dictionary that renders the book list. */
export function findLocalizedBook(term: string, books: Record<string, string>): { book: string; chapter: string; verse: string } | null {
  const normalize = (value: string) => value.normalize('NFC').replace(/[\u200B-\u200D\uFEFF]/g, '').replace(/[๐-๙]/g, digit => String(digit.charCodeAt(0) - 0x0E50)).trim().toLocaleLowerCase();
  const query = normalize(term);
  for (const [book, name] of Object.entries(books).sort((a, b) => b[1].length - a[1].length)) {
    const label = normalize(name);
    if (!query.startsWith(label)) continue;
    const tail = query.slice(label.length).trim();
    const match = tail.match(/^(?:(\d+)(?::(\d*))?)?$/);
    if (match) return { book, chapter: match[1] || '1', verse: match[2] || '' };
  }
  return null;
}
