import type React from 'react';
import { bibleBaseForEdition } from '../i18n/editions';
import { stripFbvCommentary } from '../utils/bibleTextUtils';

// A later navigation owns these setters; an older response must never replace it.
const readingRequests = new WeakMap<React.Dispatch<React.SetStateAction<any[]>>, AbortController>();
export const fetchVerse = async (
  book: string, chapter: string | number, verse: string | number,
  setData: React.Dispatch<React.SetStateAction<any[]>>,
  setVerse: React.Dispatch<React.SetStateAction<any[]>>,
  translation = 'kjv',
): Promise<void> => {
  readingRequests.get(setData)?.abort();
  const controller = new AbortController();
  readingRequests.set(setData, controller);
  const notify = (state: string) => window.dispatchEvent(new CustomEvent('bibleReadingState', { detail: state }));
  setData([]);
  setVerse([]);
  notify('loading');
  try {
    const folder = book.trim().split(' ')[0].toLowerCase();
    const ch = String(chapter).replace(/:$/, '');
    const suffix = verse === '' ? `${ch}.json` : `${ch}/verses/${verse}.json`;
    const response = await fetch(`${bibleBaseForEdition(translation)}${folder}/chapters/${suffix}`, { signal: controller.signal });
    if (!response.ok) throw new Error(`Bible HTTP ${response.status}`);
    const records = await response.json();
    if (!Array.isArray(records) || !records.length || !records.every(v => typeof v.text === 'string' && String(v.chapter) === ch)) throw new Error('Invalid Bible chapter');
    if (readingRequests.get(setData) !== controller) return;
    const data = translation === 'fbv' ? records.map(v => ({ ...v, text: stripFbvCommentary(v.text, String(v.chapter), String(v.verse)) })) : records;
    setData(data);
    setVerse(data);
    notify('ready');
  } catch (error) {
    if (controller.signal.aborted || readingRequests.get(setData) !== controller) return;
    notify('error');
    console.error('Unable to load selected Bible edition', error);
  }
};

