import { useTranslation } from '../../hooks/useTranslation';
import React, { useEffect, useState } from 'react';
import { 
  Box, 
  Typography, 
  Button, 
  Chip, 
  Paper, 
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { useSubscription } from '../../contexts/SubscriptionContext';
import { cancelSubscription } from '../../services/stripe';

/**
 * Component to display subscription status and management options.
 */
const SubscriptionStatus: React.FC = () => {
  const { t, language } = useTranslation();
  const { subscription, refreshStatus } = useSubscription();
  const [loading, setLoading] = useState(false);
  const [openDialog, setOpenDialog] = useState(false);

  const handleCancelSubscription = async () => {
    if (!subscription.subscriptionId) return;
    
    setLoading(true);
    try {
      await cancelSubscription(subscription.subscriptionId);
      await refreshStatus();
      setOpenDialog(false);
    } catch (error) {
      console.error('Error cancelling subscription:', error);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string | null) => {
    if (!dateString) return '—';
    return new Date(dateString).toLocaleDateString(language);
  };
  
  return (
    <Paper
      elevation={3}
      sx={{
        padding: 3,
        border: '1px solid',
        borderColor: 'divider',
        borderRadius: 2,
        marginBottom: 3,
        backgroundColor: (theme) =>
          theme.palette.mode === "dark" ? "#212121" : "#FFFFFF",
      }}
    >
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6" sx={{ mr: 2 }}>{String(t('subscriptionUI.status'))}</Typography>
        {subscription.isActive && (
          <Chip 
            label={String(t('readerProfile.active'))} 
            color="success" 
            size="small" 
            variant="outlined"
          />
        )}
        {!subscription.isActive && (
          <Chip 
            label={String(t('subscriptionUI.inactive'))} 
            color="error" 
            size="small" 
            variant="outlined"
          />
        )}
      </Box>

      {subscription.isActive ? (
        <>
          <Box sx={{ mb: 2, textAlign: 'right' }}>
            <Typography variant="body2" color="text.secondary" gutterBottom>{String(t('subscriptionUI.plan'))}</Typography>
            <Typography variant="body1">
              {subscription.plan === 'yearly' ? String(t('subscriptionUI.yearly')) : String(t('subscriptionUI.monthly'))}
            </Typography>
          </Box>

          {/* Check if subscription is in trial period */}
          {subscription.expiresAt && (
            <Box sx={{ mb: 2, textAlign: 'right' }}>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                {subscription.status === 'trialing' ? String(t('subscriptionUI.trialUntil')) : String(t('subscriptionUI.renewal'))}
              </Typography>
              <Typography variant="body1">
                {formatDate(subscription.expiresAt)}
              </Typography>
              {subscription.status === 'trialing' && (
                <Typography variant="body2" color="primary" sx={{ mt: 1, fontStyle: 'italic' }}>
                  {String(t('subscriptionUI.trialPayment', { date: formatDate(subscription.expiresAt) }))}
                </Typography>
              )}
            </Box>
          )}
          
          <Box sx={{ mt: 3, textAlign: 'left' }}>
            <Button 
              variant="outlined" 
              color="error"
              onClick={() => setOpenDialog(true)}
            >{String(t('subscriptionUI.cancel'))}</Button>
          </Box>
          
          {/* Cancel Confirmation Dialog */}
          <Dialog
            open={openDialog}
            onClose={() => setOpenDialog(false)}
          >
            <DialogTitle>{String(t('subscriptionUI.cancel'))}</DialogTitle>
            <DialogContent>
              <DialogContentText>{String(t('subscriptionUI.cancelConfirm'))}</DialogContentText>
            </DialogContent>
            <DialogActions>
              <Button sx={{ color: "#A1A1A1" }} onClick={() => setOpenDialog(false)}>{String(t('subscriptionUI.keep'))}</Button>
              <Button 
                onClick={handleCancelSubscription} 
                color="error"
                disabled={loading}
              >
                {loading ? <CircularProgress size={24} /> : String(t('subscriptionUI.yesCancel'))}
              </Button>
            </DialogActions>
          </Dialog>
        </>
      ) : (
        <Box>
          <Typography variant="body2" color="text.secondary" paragraph>{String(t('subscriptionUI.none'))}</Typography>
          <Button 
            variant="contained" 
            color="primary"
            component={RouterLink}
            to="/subscribe"
          >{String(t('subscriptionUI.subscribe'))}</Button>
        </Box>
      )}
    </Paper>
  );
};

export default SubscriptionStatus;